"use client";
import { useDialogContext } from "./context.js";
import { createContextPart } from "../create-context-part.js";
//#region src/ui/dialog/description.tsx
/** Renders the description announced with the dialog. */
const DialogDescription = createContextPart({
	displayName: "DialogDescription",
	tag: "p",
	useContext: useDialogContext,
	getProps: (state) => ({ id: state.descriptionId })
});
//#endregion
export { DialogDescription };
